import type { Catalogue, Command, DesignDocument, EditorSession, SessionStatus, TreeState } from '../../core';
import { EditorError, SiteDesignSession, defaultDesign } from '../../core';
import type { MessageKey, Translate } from '../i18n';
import { MediaState } from '../media/media.svelte';
import { DataState } from '../data/data.svelte';
import type { SitePartState } from '../site-parts/state.svelte';

/**
 * Reactive view of an EditorSession for the Svelte components. Every change goes through the session;
 * errors are announced (aria-live) instead of thrown at the UI.
 */
export class EditorStore {
  tree = $state.raw<TreeState>({ nodes: {}, rootIds: [] });
  catalogue = $state.raw<Catalogue | null>(null);
  selection = $state<string | null>(null);
  status = $state<SessionStatus>('loading');
  dirty = $state(false);
  canUndo = $state(false);
  canRedo = $state(false);
  revision = $state(0);
  publishedRevision = $state<number | null>(null);
  canPublish = $state(false);
  publishing = $state(false);
  conflictRevision = $state<number | null>(null);
  /** Site design (plan 04): working copy shown on the canvas, and the width/state the style controls edit. */
  readonly designSession: SiteDesignSession;
  /** Media library (plan 05-A): resolved asset URLs and the media dialog request. */
  readonly media: MediaState;
  /** Data sources and query block previews (plan 07-C). */
  readonly data: DataState;
  /** The site part being edited (plan 06), or null for a page. */
  part: SitePartState | null = null;
  design = $state.raw<DesignDocument>(defaultDesign());
  designDirty = $state(false);
  /** Breakpoint id the canvas shows and the style controls edit; null = base (smallest screens). */
  viewport = $state<string | null>(null);
  styleState = $state<string | null>(null);
  /** The site design panel replaces the inspector while open (plan 04-D). */
  designOpen = $state(false);
  designAvailable = $state(false);
  designRevision = $state(0);
  designPublished = $state<number | null>(null);
  /** Polite announcement (results) and assertive one (errors). */
  message = $state('');
  alert = $state('');
  private readonly stops: (() => void)[] = [];

  constructor(readonly session: EditorSession, readonly t: Translate) {
    this.designSession = new SiteDesignSession(session.transport);
    this.media = new MediaState(session.transport);
    this.data = new DataState(session.transport);
    this.stops.push(this.designSession.events.on('change', () => {
      this.design = this.designSession.design;
      this.designDirty = this.designSession.dirty;
      this.designRevision = this.designSession.revision;
      this.designPublished = this.designSession.publishedRevision;
      this.designAvailable = this.designSession.available;
    }));
    for (const event of ['status-change', 'dirty-change', 'history-change', 'selection-change', 'ready',
      'save-success', 'conflict', 'publish-start', 'publish-success', 'publish-error'] as const) {
      this.stops.push(session.events.on(event, () => this.sync()));
    }
    this.sync();
  }

  sync(): void {
    const s = this.session;
    this.tree = s.tree;
    this.catalogue = s.status === 'loading' || s.status === 'load-error' ? this.catalogue : s.catalogue;
    this.selection = s.selection;
    this.status = s.status;
    this.dirty = s.dirty;
    this.canUndo = s.canUndo;
    this.canRedo = s.canRedo;
    this.revision = s.baseRevision;
    this.publishedRevision = s.publishedRevision;
    this.canPublish = s.canPublish;
    this.publishing = s.publishing;
    this.conflictRevision = s.conflictRevision;
  }

  /** Something on the server is not public yet (or local edits are pending). */
  get unpublished(): boolean {
    return this.dirty || this.publishedRevision !== this.revision;
  }

  async publish(): Promise<void> {
    try {
      const revision = await this.session.publish();
      this.sync();
      this.announce('announce.published', { revision });
    } catch (error) {
      this.sync();
      this.fail(error);
    }
  }

  async resolve(choice: 'keep-mine' | 'take-theirs'): Promise<void> {
    try {
      await this.session.resolveConflict(choice);
      this.sync();
      this.announce(choice === 'keep-mine' ? 'announce.keptMine' : 'announce.tookTheirs', { revision: this.revision });
    } catch (error) {
      this.sync();
      this.fail(error);
    }
  }

  announce(key: MessageKey, params: Record<string, string | number> = {}): void {
    this.message = this.t(key, params);
    this.alert = '';
  }

  fail(error: unknown, code = error instanceof EditorError ? error.code : 'SERVER'): void {
    this.alert = this.t(`error.${code}` as MessageKey);
  }

  /** Runs a command; returns false (and announces why) when the core refuses it. */
  run(command: Command, announce?: [MessageKey, Record<string, string | number>?]): boolean {
    try {
      this.session.dispatch(command);
      this.sync();
      if (announce) this.announce(announce[0], announce[1]);
      return true;
    } catch (error) {
      this.fail(error);
      return false;
    }
  }

  undo(): void {
    this.guard(() => this.session.undo());
  }

  redo(): void {
    this.guard(() => this.session.redo());
  }

  select(id: string | null): void {
    this.session.select(id);
    this.sync();
  }

  async save(): Promise<void> {
    try {
      const revision = await this.session.save('edit');
      this.sync();
      if (revision !== null) this.announce('announce.saved', { revision });
    } catch (error) {
      this.sync();
      this.fail(error);
    }
  }

  async loadDesign(): Promise<void> {
    await this.designSession.load();
  }

  /** Saves or publishes the site design; errors (conflict, validation) are announced, never thrown at the UI. */
  async designAction(action: 'save' | 'publish' | 'reload'): Promise<void> {
    try {
      if (action === 'reload') await this.designSession.reload();
      const revision = action === 'save' ? await this.designSession.save()
        : action === 'publish' ? await this.designSession.publish() : this.designSession.revision;
      this.designRevision = this.designSession.revision;
      this.designPublished = this.designSession.publishedRevision;
      this.announce(action === 'publish' ? 'design.published' : action === 'save' ? 'design.saved' : 'design.reloaded', { revision });
    } catch (error) {
      this.fail(error);
    }
  }

  destroy(): void {
    for (const stop of this.stops) stop();
  }

  private guard(action: () => void): void {
    try {
      action();
    } catch (error) {
      this.fail(error);
    }
    this.sync();
  }
}
